#[summary("account ledger")]
mod tasks {
    spec fn elem_ok(kinds: &[i64], amounts: &[i64], k: usize) -> bool {
        k < kinds.len() && k < amounts.len() && 0 <= kinds[k] && kinds[k] <= 3 && amounts[k] >= 0
    }

    spec fn idx_lt(kinds: &[i64], k: usize) -> bool {
        k < kinds.len()
    }

    spec fn idx_ok(kinds: &[i64], amounts: &[i64], k: usize) -> bool {
        k <= kinds.len() && kinds.len() == amounts.len()
    }

    spec fn inputs_ok(kinds: &[i64], amounts: &[i64], start: i64) -> bool {
        kinds.len() == amounts.len() && start >= 0 && (forall|i: usize| i < kinds.len() ==> 0 <= #[trigger] kinds[i] && kinds[i] <= 3 && amounts[i] >= 0)
    }

    #[effects(io)]
    #[uses(elem_ok, idx_ok, inputs_ok, mul_post, mul_pre, nonneg)]
    fn ledger(kinds: &[i64], amounts: &[i64], start: i64) -> (r: i64)
        requires inputs_ok(kinds, amounts, start),
        ensures nonneg(r),
    {
        let mut bal: i64 = start;
        let mut k: usize = 0;
        while k < kinds.len()
            invariant inputs_ok(kinds, amounts, start), nonneg(bal), idx_ok(kinds, amounts, k),
            decreases kinds.len() - k,
        {
            let kind: i64 = kinds[k];
            let amt: i64 = amounts[k];
            let mut out: i64 = -1;
            if kind == 0 {
                if amt <= 9223372036854775807 - bal {
                    bal = bal + amt;
                    out = bal;
                }
            } else if kind == 1 {
                if amt <= bal {
                    bal = bal - amt;
                    out = bal;
                }
            } else if kind == 2 {
                let q: i64 = bal / 100;
                if amt == 0 {
                    out = bal;
                } else if q <= (9223372036854775807 - bal) / amt {
                    let inc: i64 = safe_mul(q, amt, 9223372036854775807 - bal);
                    bal = bal + inc;
                    out = bal;
                }
            } else {
                if amt <= bal {
                    bal = bal - amt;
                } else {
                    bal = 0;
                }
                out = bal;
            }
            print_i64(out);
            k = k + 1;
        }
        bal
    }

    spec fn mul_post(q: i64, a: i64, m: i64, p: i64) -> bool {
        p == q * a && 0 <= p && p <= m
    }

    spec fn mul_pre(q: i64, a: i64, m: i64) -> bool {
        q >= 0 && a > 0 && m >= 0 && q <= m / a
    }

    spec fn nonneg(x: i64) -> bool {
        x >= 0
    }

    #[effects(pure)]
    #[uses(mul_post, mul_pre)]
    fn safe_mul(q: i64, a: i64, m: i64) -> (p: i64)
        requires mul_pre(q, a, m),
        ensures mul_post(q, a, m, p),
    {
        q * a
    }
}

#[summary("report tasks")]
mod tasks {
    spec fn inv(i: usize, len: usize, cnt: i64, cur: i64, best: i64) -> bool {
        i <= len && 0 <= cnt && cnt <= i && 0 <= cur && cur <= i && 0 <= best && best <= i
    }

    spec fn is_floor_mid(m: i64, mn: i64, mx: i64) -> bool {
        2 * m <= mn + mx && mn + mx < 2 * m + 2
    }

    #[effects(pure)]
    #[uses(is_floor_mid, ord)]
    fn midpoint(mn: i64, mx: i64) -> (m: i64)
        requires ord(mn, mx),
        ensures is_floor_mid(m, mn, mx),
    {
        if mn < 0 && mx >= 0 {
            let s: i64 = mn + mx;
            if s >= 0 {
                s / 2
            } else {
                let h: i64 = s / 2;
                if h * 2 == s {
                    h
                } else {
                    h - 1
                }
            }
        } else {
            mn + (mx - mn) / 2
        }
    }

    spec fn ord(mn: i64, mx: i64) -> bool {
        mn <= mx
    }

    #[effects(io)]
    #[uses(inv, ord, res_ok)]
    fn report(a: &[i64], t: i64) -> (r: i64)
        ensures res_ok(r, a.len()),
    {
        if a.len() == 0 {
            0
        } else {
            let mut mn: i64 = a[0];
            let mut mx: i64 = a[0];
            let mut cnt: i64 = 0;
            let mut cur: i64 = 0;
            let mut best: i64 = 0;
            let mut i: usize = 0;
            while i < a.len()
                invariant inv(i, a.len(), cnt, cur, best), ord(mn, mx),
                decreases a.len() - i,
            {
                let x: i64 = a[i];
                if x < mn {
                    mn = x;
                }
                if x > mx {
                    mx = x;
                }
                if x > t {
                    cnt = cnt + 1;
                    cur = cur + 1;
                    if cur > best {
                        best = cur;
                    }
                } else {
                    cur = 0;
                }
                i = i + 1;
            }
            print_i64(mn);
            print_i64(mx);
            print_i64(tasks::midpoint(mn, mx));
            print_i64(cnt);
            best
        }
    }

    spec fn res_ok(r: i64, len: usize) -> bool {
        0 <= r && r <= len
    }
}

#[summary("Token bucket rate limiter")]
mod tasks {
    spec fn adj_sorted(t: &[i64]) -> bool {
        forall|i: usize| i + 1 < t.len() ==> #[trigger] t[i] <= t[i + 1]
    }

    spec fn count_ok(r: i64, n: usize) -> bool {
        0 <= r && r <= n
    }

    spec fn inv(t: &[i64], k: usize, cap: i64, every: i64, tokens: i64, mark: i64, cnt: i64) -> bool {
        k <= t.len() && 0 <= tokens && tokens <= cap && 0 <= mark && 0 <= cnt && cnt <= k && (k == 0 || mark <= t[k - 1]) && (k < t.len() ==> mark <= t[k])
    }

    #[effects(io)]
    #[uses(adj_sorted, count_ok, inv, nonneg, params_ok)]
    fn limiter(times: &[i64], cap: i64, every: i64) -> (r: i64)
        requires nonneg(times), adj_sorted(times), params_ok(cap, every),
        ensures count_ok(r, times.len()),
    {
        let mut k: usize = 0;
        let mut tokens: i64 = cap;
        let mut mark: i64 = 0;
        let mut cnt: i64 = 0;
        while k < times.len()
            invariant inv(times, k, cap, every, tokens, mark, cnt), nonneg(times), adj_sorted(times), params_ok(cap, every),
            decreases times.len() - k,
        {
            let t: i64 = times[k];
            let d: i64 = t - mark;
            let g: i64 = d / every;
            assert(g * every <= d);
            assert(g >= 0);
            let room: i64 = cap - tokens;
            if g >= room {
                tokens = cap;
            } else {
                tokens = tokens + g;
            }
            mark = mark + g * every;
            if tokens >= 1 {
                tokens = tokens - 1;
                cnt = cnt + 1;
                print_i64(1);
            } else {
                print_i64(0);
            }
            k = k + 1;
        }
        cnt
    }

    spec fn nonneg(t: &[i64]) -> bool {
        forall|i: usize| i < t.len() ==> 0 <= #[trigger] t[i]
    }

    spec fn params_ok(cap: i64, every: i64) -> bool {
        0 <= cap && 1 <= every
    }
}

#[summary("run-length encoding printer")]
mod tasks {
    spec fn lim_ok(limit: i64) -> bool {
        limit >= 1
    }

    spec fn outer_inv(i: usize, n: usize, a: &[i64], count: i64) -> bool {
        i <= n && n == a.len() && 0 <= count && count <= i
    }

    spec fn piece_inv(j: usize, run: i64, rem: i64, count: i64) -> bool {
        0 <= rem && rem <= run && 0 <= count && count <= j - rem
    }

    spec fn pos(x: i64) -> bool {
        x >= 1
    }

    spec fn res_ok(r: i64, a: &[i64]) -> bool {
        r >= 0 && r <= a.len() && (a.len() == 0 ==> r == 0)
    }

    #[effects(io)]
    #[uses(lim_ok, outer_inv, piece_inv, res_ok, run_inv)]
    fn rle(a: &[i64], limit: i64) -> (r: i64)
        requires lim_ok(limit),
        ensures res_ok(r, a),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut count: i64 = 0;
        while i < n
            invariant outer_inv(i, n, a, count),
            decreases n - i,
        {
            let v: i64 = a[i];
            let mut j: usize = i;
            let mut run: i64 = 0;
            while j < n && a[j] == v
                invariant run_inv(i, j, n, run), n == a.len(),
                decreases n - j,
            {
                j = j + 1;
                run = run + 1;
            }
            let mut rem: i64 = run;
            while rem > 0
                invariant piece_inv(j, run, rem, count), lim_ok(limit),
                decreases rem,
            {
                let len: i64 = if rem < limit {
                    rem
                } else {
                    limit
                };
                print_i64(v);
                print_i64(len);
                rem = rem - len;
                count = count + 1;
            }
            i = j;
        }
        count
    }

    spec fn run_inv(i: usize, j: usize, n: usize, run: i64) -> bool {
        i <= j && j <= n && run == j - i
    }
}
